
.panel {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 8px 12px;
}

.panel-title {
  font-weight: bold;
  color: var(--c-primary);
  margin-bottom: 6px;
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 4px;
}

.empty {
  color: var(--c-text-muted);
  font-size: 12px;
}

.maid-row {
  padding: 6px 0;
  border-bottom: 1px dashed var(--c-border);
}

.maid-row:last-child {
  border-bottom: none;
}

.maid-row.away {
  opacity: 0.6;
}

.maid-main {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.maid-name {
  font-weight: bold;
  color: var(--c-text);
}

.maid-away {
  font-size: 11px;
  color: var(--c-text-muted);
}

.maid-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 3px 0;
}

.tag {
  background: var(--c-primary-soft);
  color: var(--c-primary);
  border-radius: 8px;
  padding: 0 8px;
  font-size: 11px;
}

.tag.state {
  background: var(--c-surface-alt);
  color: var(--c-text-muted);
}

.maid-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  font-size: 12px;
  color: var(--c-text-muted);
}

.maid-event {
  margin-top: 3px;
  font-size: 11px;
  color: var(--c-warn);
}
