
.panel {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 8px 12px;
}

.panel-title {
  font-weight: bold;
  color: var(--c-primary);
  margin-bottom: 6px;
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 4px;
}

.player-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  font-size: 12px;
  color: var(--c-text-muted);
}

.task {
  margin-top: 6px;
  display: flex;
  gap: 8px;
  font-size: 12px;
}

.task-label {
  color: var(--c-warn);
  font-weight: bold;
  white-space: nowrap;
}

.task-text {
  color: var(--c-text);
}

.sub-list {
  margin-top: 6px;
  border-top: 1px dashed var(--c-border);
  padding-top: 4px;
}

.sub-item {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
}

.sub-name {
  color: var(--c-primary);
  font-weight: bold;
}

.sub-desc {
  color: var(--c-text-muted);
  text-align: right;
}
