
.panel {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 8px 12px;
}

.panel-title {
  font-weight: bold;
  color: var(--c-primary);
  margin-bottom: 6px;
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 4px;
}

.estate-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 6px 12px;
}

.stat {
  display: flex;
  flex-direction: column;
}

.stat-label {
  font-size: 11px;
  color: var(--c-text-muted);
}

.stat-value {
  font-weight: bold;
}

.coin {
  color: var(--c-accent);
}

.sub-list {
  margin-top: 6px;
  border-top: 1px dashed var(--c-border);
  padding-top: 4px;
}

.sub-item {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
}

.sub-name {
  color: var(--c-primary);
  font-weight: bold;
}

.sub-name.todo {
  color: var(--c-warn);
}

.sub-desc {
  color: var(--c-text-muted);
  text-align: right;
}
